import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.junit.jupiter.api.Test;

class CustomerFilterTest {

    private static final Customer ADA = new Customer(
            1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
    private static final Customer MAKINEN = new Customer(
            2, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.PENDING);
    private static final Customer JOSEPHINE = new Customer(
            3, "Joséphine", "Engberg", "josephine@example.com", "Denmark", CustomerStatus.CLOSED);

    @Test
    void emptyFilterMatchesEverything() {
        assertTrue(CustomerFilter.EMPTY.matches(ADA));
        assertTrue(new CustomerFilter("   ", Set.of()).matches(MAKINEN));
    }

    @Test
    void everyTermMustMatchFirstOrLastName() {
        assertTrue(new CustomerFilter("ada aal", Set.of()).matches(ADA));
        assertTrue(new CustomerFilter("aal ada", Set.of()).matches(ADA));
        assertFalse(new CustomerFilter("ada virtanen", Set.of()).matches(ADA));
    }

    @Test
    void whitespaceIsNotSignificant() {
        assertTrue(new CustomerFilter("  ada   aal  ", Set.of()).matches(ADA));
    }

    @Test
    void matchingIgnoresCaseAndAccentsBothWays() {
        assertTrue(new CustomerFilter("makinen", Set.of()).matches(MAKINEN));
        assertTrue(new CustomerFilter("MAKINEN", Set.of()).matches(MAKINEN));
        assertTrue(new CustomerFilter("mäkinen", Set.of()).matches(MAKINEN));
        assertTrue(new CustomerFilter("josephine", Set.of()).matches(JOSEPHINE));
    }

    @Test
    void statusFilterWithNothingSelectedMatchesEverything() {
        assertTrue(new CustomerFilter("", Set.of()).matches(ADA));
    }

    @Test
    void statusFilterRestrictsToSelectedStatuses() {
        assertTrue(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)).matches(ADA));
        assertFalse(new CustomerFilter("", Set.of(CustomerStatus.PENDING)).matches(ADA));
        assertTrue(new CustomerFilter("", Set.of(CustomerStatus.PENDING, CustomerStatus.CLOSED)).matches(MAKINEN));
    }

    @Test
    void bothFiltersMustMatch() {
        CustomerFilter filter = new CustomerFilter("ada", Set.of(CustomerStatus.PENDING));
        assertFalse(filter.matches(ADA));
    }
}
