+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * A filter applied to the customer list.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ * <ul>
+ *     <li>{@code name} is split on whitespace into terms, and every term must
+ *     appear as a substring of the customer's first name or last name.
+ *     Matching ignores case and accents.</li>
+ *     <li>{@code statuses}, when non-empty, must contain the customer's
+ *     status. An empty set matches every status.</li>
+ * </ul>
+ *
+ * @param name     free-text name filter; may be blank
+ * @param statuses statuses to include; empty means "any status"
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Whether the given customer satisfies both the name and status filters. */
+    public boolean matches(Customer customer) {
+        return matchesStatus(customer) && matchesName(customer);
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private boolean matchesName(Customer customer) {
+        List<String> terms = nameTerms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private List<String> nameTerms() {
+        return Arrays.stream(name.trim().split("\\s+"))
+                .filter(term -> !term.isBlank())
+                .map(CustomerFilter::normalize)
+                .toList();
+    }
+
+    private static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        String withoutAccents = decomposed.replaceAll("\\p{M}", "");
+        return withoutAccents.toLowerCase(Locale.ROOT);
+    }
+}
